const rows: readonly Row[] = [...Object.values(researchStaticCopy), ...Object.values(nativeResearchPlanCopy), ...Object.values(nativeResearchCopy), ...Object.values(conversationCopy), ...Object.values(researchDocumentCopyRows)]
/** Call only on explicit system/static fixture copy, not titles, inputs or supplied prose. */
export function researchStaticText(value: string, language: ClientLanguage): string {
  if (isClientResearchSystemLabel(value)) return clientResearchLabel(value, language)
  const row = rows.find(candidate => candidate[0] === value)
  return row ? row[column[language]] : clientResearchLabel(value, language)
}
