export function researchStaticFormat(key: keyof typeof researchStaticTemplates, language: ClientLanguage, values: Readonly<Record<string, string | number>>): string {
  const one = (value: string | number | undefined) => new Intl.PluralRules(language).select(Number(value)) === 'one'
  let row: Row = language !== 'ko' && one(values.count) ? researchStaticSingularCopy[key] ?? researchStaticTemplates[key] : researchStaticTemplates[key]
  if (language !== 'ko' && key === 'integrity') {
    const backtestOne = one(values.backtests), revisionOne = one(values.revisions)
    if (backtestOne || revisionOne) row = researchIntegritySingularCopy[backtestOne && revisionOne ? 'integrityBothOne' : backtestOne ? 'integrityBacktestOne' : 'integrityRevisionOne']
  }
  return row[column[language]].replace(/\{(\w+)\}/g, (token, name: string) => Object.hasOwn(values, name) ? String(values[name]) : token)
}

